#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  $exe=".exe"
}
$ret=0
if (Test-Path "$basedir/node$exe") {
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../.deno/swagger-jsdoc@6.3.0/node_modules/swagger-jsdoc/bin/swagger-jsdoc.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../.deno/swagger-jsdoc@6.3.0/node_modules/swagger-jsdoc/bin/swagger-jsdoc.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../.deno/swagger-jsdoc@6.3.0/node_modules/swagger-jsdoc/bin/swagger-jsdoc.js" $args
  } else {
    & "node$exe"  "$basedir/../.deno/swagger-jsdoc@6.3.0/node_modules/swagger-jsdoc/bin/swagger-jsdoc.js" $args
  }
  $ret=$LASTEXITCODE
}
exit $ret
